process::WFP Seed Workforce Input.PrologProcedure:
#Region Seed Workforce Input — FTE + Base Salary per active month (rev D dim order: Period, Version, Position, Measure)
cCube = 'WFP Workforce Input';
cPos  = 'WFP Position';
cPer  = 'WFP Period';

nPosCount = DIMSIZ( cPos );
nPerCount = DIMSIZ( cPer );

nI = 1;
WHILE( nI <= nPosCount );
   vPos = DIMNM( cPos, nI );
   IF( DTYPE( cPos, vPos ) @= 'N' );
      nFTE = ATTRN( cPos, vPos, 'FTE' );
      nSal = ATTRN( cPos, vPos, 'Seed Base Salary' );
      vStartPd = ATTRS( cPos, vPos, 'Start Period' );
      vEndPd = ATTRS( cPos, vPos, 'End Period' );
      nStartIdx = ATTRN( cPer, vStartPd, 'Period Index' );
      nEndIdx = IF( vEndPd @= '', 999, ATTRN( cPer, vEndPd, 'Period Index' ) );

      nP = 1;
      WHILE( nP <= nPerCount );
         vPer = DIMNM( cPer, nP );
         IF( DTYPE( cPer, vPer ) @= 'N' );
            nPidx = ATTRN( cPer, vPer, 'Period Index' );
            IF( nPidx >= nStartIdx & nPidx <= nEndIdx );
               CellPutN( nFTE, cCube, vPer, 'Budget',   vPos, 'FTE' );
               CellPutN( nSal, cCube, vPer, 'Budget',   vPos, 'Base Salary' );
               CellPutN( nFTE, cCube, vPer, 'Working',  vPos, 'FTE' );
               CellPutN( nSal, cCube, vPer, 'Working',  vPos, 'Base Salary' );
            ENDIF;
         ENDIF;
         nP = nP + 1;
      END;
   ENDIF;
   nI = nI + 1;
END;

process::WFP Create Default Subsets.PrologProcedure:
#Region Default subset on every WFP model dimension (rev D)
vList = 'WFP Cost Centre~WFP Currency~WFP Entity~WFP FX Rate Type~WFP FX Rates Measure~WFP Grade~WFP Headcount Measure~WFP Job Family~WFP Jurisdiction~WFP Location~WFP Pay Component~WFP Pay Rates Measure~WFP Period~WFP Position~WFP Tax Band~WFP Tax Bands Measure~WFP Tax Type~WFP Version~WFP Workforce Cost Measure~WFP Workforce Input Measure~';

WHILE( SCAN( '~', vList ) > 1 );
   nS = SCAN( '~', vList );
   vDim = SUBST( vList, 1, nS - 1 );
   vList = SUBST( vList, nS + 1, LONG( vList ) - nS );

   IF( SubsetExists( vDim, 'Default' ) = 0 );
      SubsetCreate( vDim, 'Default' );
   ELSE;
      SubsetDeleteAllElements( vDim, 'Default' );
   ENDIF;

   nE = 1;
   nEcount = DIMSIZ( vDim );
   WHILE( nE <= nEcount );
      SubsetElementInsert( vDim, 'Default', DIMNM( vDim, nE ), nE );
      nE = nE + 1;
   END;
END;

process::WFP Seed FX Rates.PrologProcedure:
#Region Seed FX rates — 1 unit of currency in the reporting currency (GBP). rev D order: Period, Version, Currency, FX Rate Type, Measure
cCube = 'WFP FX Rates';
cPer  = 'WFP Period';
nPcount = DIMSIZ( cPer );

vC = 'GBP;1~USD;0.79~NZD;0.47~Reporting;1~';

WHILE( SCAN( '~', vC ) > 1 );
   nS = SCAN( '~', vC );
   vRec = SUBST( vC, 1, nS - 1 ) | ';';
   vC = SUBST( vC, nS + 1, LONG( vC ) - nS );

   nS = SCAN(';',vRec); vCur = SUBST(vRec,1,nS-1); vRec = SUBST(vRec,nS+1,LONG(vRec)-nS);
   nS = SCAN(';',vRec); nRate = NUMBR(SUBST(vRec,1,nS-1));

   nP = 1;
   WHILE( nP <= nPcount );
      vPer = DIMNM( cPer, nP );
      IF( DTYPE( cPer, vPer ) @= 'N' );
         vVl = 'Budget|Working|';
         WHILE( SCAN( '|', vVl ) > 1 );
            nS = SCAN( '|', vVl );
            vVer = SUBST( vVl, 1, nS - 1 );
            vVl = SUBST( vVl, nS + 1, LONG( vVl ) - nS );
            CellPutN( nRate, cCube, vPer, vVer, vCur, 'Average', 'Rate' );
            CellPutN( nRate, cCube, vPer, vVer, vCur, 'Closing', 'Rate' );
         END;
      ENDIF;
      nP = nP + 1;
   END;
END;

process::WFP Seed Pay Rates.PrologProcedure:
