process::WFP Seed Workforce Input.PrologProcedure:
#Region Seed Workforce Input — FTE + Base Salary per active month (Period, Version, Position, Measure)
# Budget + Working = seed defaults. Actual = same as Working, EXCEPT a real
# in-year raise: EXEC-001 to 220,000 for 2026-01..2026-03 (closed months) so the
# Forecast blend (Actual for <= Actuals Cutoff Index, else Working) is visible.
cCube = 'WFP Workforce Input';
cPos  = 'WFP Position';
cPer  = 'WFP Period';

nPosCount = DIMSIZ( cPos );
nPerCount = DIMSIZ( cPer );

nI = 1;
WHILE( nI <= nPosCount );
   vPos = DIMNM( cPos, nI );
   IF( DTYPE( cPos, vPos ) @= 'N' );
      nFTE = ATTRN( cPos, vPos, 'FTE' );
      nSal = ATTRN( cPos, vPos, 'Seed Base Salary' );
      vStartPd = ATTRS( cPos, vPos, 'Start Period' );
      vEndPd = ATTRS( cPos, vPos, 'End Period' );
      nStartIdx = ATTRN( cPer, vStartPd, 'Period Index' );
      nEndIdx = IF( vEndPd @= '', 999, ATTRN( cPer, vEndPd, 'Period Index' ) );

      nP = 1;
      WHILE( nP <= nPerCount );
         vPer = DIMNM( cPer, nP );
         IF( DTYPE( cPer, vPer ) @= 'N' );
            nPidx = ATTRN( cPer, vPer, 'Period Index' );
            IF( nPidx >= nStartIdx & nPidx <= nEndIdx );
               CellPutN( nFTE, cCube, vPer, 'Budget',   vPos, 'FTE' );
               CellPutN( nSal, cCube, vPer, 'Budget',   vPos, 'Base Salary' );
               CellPutN( nFTE, cCube, vPer, 'Working',  vPos, 'FTE' );
               CellPutN( nSal, cCube, vPer, 'Working',  vPos, 'Base Salary' );

               # Actual: mirrors Working, with the EXEC-001 raise for closed months
               nActSal = nSal;
               IF( vPos @= 'EXEC-001' & nPidx >= 13 & nPidx <= 15 );
                  nActSal = 220000;
               ENDIF;
               CellPutN( nFTE,    cCube, vPer, 'Actual', vPos, 'FTE' );
               CellPutN( nActSal, cCube, vPer, 'Actual', vPos, 'Base Salary' );
            ENDIF;
         ENDIF;
         nP = nP + 1;
      END;
   ENDIF;
   nI = nI + 1;
END;

