process::WFP Seed Assumptions.PrologProcedure:
#Region Seed WFP Assumptions — global planning drivers, per Period x Version x Entity
# Idempotent. Written at the LEAF entities only (Group is a consolidation and
# rates don't sum); rules read assumptions at the position's Home Entity (a leaf).
# Same values across all periods/versions/entities for now — edit per cell after
# where a driver should vary (e.g. Merit % by year).
cCube = 'WFP Assumptions';
cPer  = 'WFP Period';
nPcount = DIMSIZ( cPer );

# measure ; value
vM =
'Merit Increase %;0.03~' |
'Promotion Budget %;0.01~' |
'Inflation %;0.025~' |
'Actuals Cutoff Index;15~' |
'Vacancy Allowance %;0.10~' |
'Standard FTE Hours;160~' |
'Bonus Pool %;0.10~' |
'Employer Oncost Fallback %;0.15~';

vVers = 'Budget|Working|Forecast|';
vEnts = 'UK Ltd|US Inc|NZ Ltd|';

nP = 1;
WHILE( nP <= nPcount );
   vPer = DIMNM( cPer, nP );
   IF( DTYPE( cPer, vPer ) @= 'N' & LONG( vPer ) = 7 );
      vVl = vVers;
      WHILE( SCAN( '|', vVl ) > 1 );
         nS = SCAN( '|', vVl ); vVer = SUBST( vVl, 1, nS - 1 ); vVl = SUBST( vVl, nS + 1, LONG( vVl ) - nS );
         vEl = vEnts;
         WHILE( SCAN( '|', vEl ) > 1 );
            nS = SCAN( '|', vEl ); vEnt = SUBST( vEl, 1, nS - 1 ); vEl = SUBST( vEl, nS + 1, LONG( vEl ) - nS );
            vRows = vM;
            WHILE( SCAN( '~', vRows ) > 1 );
               nS = SCAN( '~', vRows ); vRec = SUBST( vRows, 1, nS - 1 ) | ';'; vRows = SUBST( vRows, nS + 1, LONG( vRows ) - nS );
               nS = SCAN( ';', vRec ); vMeas = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
               nS = SCAN( ';', vRec ); nVal  = NUMBR( SUBST( vRec, 1, nS - 1 ) );
               CellPutN( nVal, cCube, vPer, vVer, vEnt, vMeas );
            END;
         END;
      END;
   ENDIF;
   nP = nP + 1;
END;

process::WFP Copy Version.PrologProcedure:
#Region WFP Copy Version — copy Workforce Input (FTE + Base Salary) from one version to another
# Use to freeze Working -> Budget, or spin a named scenario off Actual.
cCube = 'WFP Workforce Input';
cPos  = 'WFP Position';
cPer  = 'WFP Period';

nStop = 0;
IF( DIMIX( 'WFP Version', pSource ) = 0 );
   ASCIIOUTPUT( 'WFP_Copy_Version_error.txt', 'Source version not found: ' | pSource );
   nStop = 1;
ENDIF;
IF( DIMIX( 'WFP Version', pTarget ) = 0 );
   ASCIIOUTPUT( 'WFP_Copy_Version_error.txt', 'Target version not found: ' | pTarget );
   nStop = 1;
ENDIF;
IF( nStop = 0 & ATTRS( 'WFP Version', pTarget, 'Version Type' ) @= 'Calculated' );
   ASCIIOUTPUT( 'WFP_Copy_Version_error.txt', 'Refused: target "' | pTarget | '" is a calculated version (rule-driven).' );
   nStop = 1;
ENDIF;

IF( nStop = 0 );
   nFromIdx = IF( pFromPeriod @= '', 0,    ATTRN( cPer, pFromPeriod, 'Period Index' ) );
   nToIdx   = IF( pToPeriod   @= '', 9999, ATTRN( cPer, pToPeriod,   'Period Index' ) );

   nPosCount = DIMSIZ( cPos );
   nPerCount = DIMSIZ( cPer );
   nCopied = 0;

   nI = 1;
   WHILE( nI <= nPosCount );
      vPos = DIMNM( cPos, nI );
      IF( DTYPE( cPos, vPos ) @= 'N' );
         nP = 1;
         WHILE( nP <= nPerCount );
            vPer = DIMNM( cPer, nP );
            IF( DTYPE( cPer, vPer ) @= 'N' & LONG( vPer ) = 7 );
               nIdx = ATTRN( cPer, vPer, 'Period Index' );
               IF( nIdx >= nFromIdx & nIdx <= nToIdx );
                  CellPutN( CellGetN( cCube, vPer, pSource, vPos, 'FTE' ),         cCube, vPer, pTarget, vPos, 'FTE' );
                  CellPutN( CellGetN( cCube, vPer, pSource, vPos, 'Base Salary' ), cCube, vPer, pTarget, vPos, 'Base Salary' );
                  nCopied = nCopied + 2;
               ENDIF;
            ENDIF;
            nP = nP + 1;
         END;
      ENDIF;
      nI = nI + 1;
   END;

   ASCIIOUTPUT( 'WFP_Copy_Version_ok.txt', 'Copied ' | NUMBERTOSTRING( nCopied ) | ' cells from ' | pSource | ' to ' | pTarget );
ENDIF;
